      "installAndroidTitle": "Instalar BudGanja en el móvil",
      "installAndroidBody": "<p>En Chrome: toca <strong>⋮</strong> (esquina superior) y elige <strong>Instalar app</strong> o <strong>Añadir a la pantalla de inicio</strong>.</p><p>Si no aparece la opción: elimina el icono antiguo (si existe), abre el sitio en Chrome, espera unos segundos e inténtalo de nuevo con este botón.</p><p class=\"pwa-install-sheet-tip\">Consejo: usa el enlace seguro del sitio (https) y mantén la página abierta mientras instalas.</p>",
