      "installDesktopTitle": "Installer BudGanja sur l’ordinateur",
      "installDesktopBody": "<p>Dans Chrome ou Edge : menu <strong>⋮ → Installer Inspetor BudGanja…</strong> (ou l’icône ⊕ / ordinateur dans la barre d’adresse).</p><p>Dans la fenêtre d’installation, cochez <strong>Créer un raccourci sur le Bureau</strong> pour que l’icône apparaisse sur le bureau.</p>",
      "installAndroidTitle": "Installer BudGanja sur le téléphone",
      "installAndroidBody": "<p>Dans Chrome : touchez <strong>⋮</strong> (coin supérieur) et choisissez <strong>Installer l’application</strong> ou <strong>Ajouter à l’écran d’accueil</strong>.</p><p>Si l’option n’apparaît pas : retirez l’ancienne icône (s’il y en a une), ouvrez le site dans Chrome, attendez quelques secondes, puis réessayez avec ce bouton.</p><p class=\"pwa-install-sheet-tip\">Astuce : utilisez le lien sécurisé du site (https) et gardez la page ouverte pendant l’installation.</p>",
