      "installAlreadyBody": "<p>BudGanja tourne déjà comme application sur cet appareil. Cherchez l’icône sur l’écran d’accueil ou dans le tiroir d’apps.</p><p>Si l’ancienne icône est cassée, retirez-la et installez à nouveau depuis le menu du site.</p>",
