      "installDesktopTitle": "कंप्यूटर पर BudGanja इंस्टॉल करें",
      "installDesktopBody": "<p>Chrome या Edge में: मेनू <strong>⋮ → Inspetor BudGanja इंस्टॉल करें…</strong> (या एड्रेस बार में ⊕ / कंप्यूटर आइकन)।</p><p>इंस्टॉल विंडो में <strong>डेस्कटॉप शॉर्टकट बनाएँ</strong> चुनें ताकि आइकन डेस्कटॉप पर दिखे।</p>",
      "installAndroidTitle": "फ़ोन पर BudGanja इंस्टॉल करें",
      "installAndroidBody": "<p>Chrome में: <strong>⋮</strong> (ऊपरी कोना) टैप करें और <strong>ऐप इंस्टॉल करें</strong> या <strong>होम स्क्रीन पर जोड़ें</strong> चुनें।</p><p>अगर विकल्प न दिखे: पुराना आइकन हटाएँ (अगर हो), Chrome में साइट खोलें, कुछ सेकंड रुकें, फिर इस बटन से फिर कोशिश करें।</p><p class=\"pwa-install-sheet-tip\">सुझाव: साइट का सुरक्षित लिंक (https) इस्तेमाल करें और इंस्टॉल करते समय पेज खुला रखें।</p>",
      "installAlreadyTitle": "ऐप पहले से इंस्टॉल है",
